// Mapeamento das colunas da planilha para o payload da API Next.js / Supabase
const item = $input.first().json;

// Suporte a diferentes nomenclaturas de colunas comuns em planilhas
const description = item['Descrição'] || item['Descricao'] || item['Estabelecimento'] || item['Description'];
const amountRaw = item['Valor'] || item['Quantia'] || item['Amount'];
const typeRaw = (item['Tipo'] || item['Type'] || 'Despesa').toLowerCase();
const category = item['Categoria'] || item['Category'] || 'Geral';
const date = item['Data'] || item['Date'] || new Date().toISOString().split('T')[0];
const paymentMethod = item['Forma de Pagamento'] || item['Metodo'] || 'Cartão';

// Conversão de tipo
const type = typeRaw.includes('receita') || typeRaw.includes('entrada') || typeRaw === 'income' ? 'income' : 'expense';

return [
  {
    json: {
      user_id: $env.DEFAULT_USER_ID || '00000000-0000-0000-0000-000000000000',
      description: String(description),
      amount: amountRaw,
      type: type,
      category_name: String(category),
      date: String(date),
      payment_method: String(paymentMethod),
      source: 'google_sheets',
      notify_telegram: true
    }
  }
];
